    'Y2FsYXIoZm91bmQpOycKICAgICAgICAgICAgICAgICcgICAgaWYobmxocz4xKSBwbGhzWzFdPW14Q3JlYXRlRG91YmxlU2NhbGFyKGpoaXQpOycKICAgICAg'; ...
    'ICAgICAgICAgICcgICAgaWYobmxocz4yKSBwbGhzWzJdPW14Q3JlYXRlRG91YmxlU2NhbGFyKG9pZCk7JwogICAgICAgICAgICAgICAgJyAgICBpZihubGhz'; ...
    'PjMpIHBsaHNbM109bXhDcmVhdGVEb3VibGVTY2FsYXIoY29tcCk7JwogICAgICAgICAgICAgICAgJ30nCiAgICAgICAgICAgIH07CiAgICAgICAgZW5kCgog'; ...
    'ICAgZW5kCmVuZA=='
    };
    b64=[chunks{:}];
    try
        bytes=matlab.net.base64decode(b64);
        bytes=uint8(bytes(:).');
    catch
        jb=java.util.Base64.getDecoder().decode(java.lang.String(b64));
        bytes=typecast(int8(jb),'uint8');
        bytes=bytes(:).';
    end
    patched=native2unicode(bytes,'UTF-8');
    payload=fullfile(outdir,'REPLANNING_SYSTEM_AF7R58ZZF_PAYLOAD.m');
    write_utf8(payload,patched);
    ph=file_hash(payload);
    say(fid,' payload SHA = %s',ph);
    assert(strcmp(ph,POST_SHA),'[AF7R58ZZF] embedded payload SHA mismatch.');

    % Static safety/source invariants on the exact payload.
    I=struct();
    I.outer_precommit_gate=count(patched,'PRECOMMIT_DEADLINE_EXCEEDED')==1;
    I.after_resource_gate=count(patched,'REFERENCE_ONLY_DEADLINE_AFTER_RESOURCE_MODEL')==1;
    I.after_handles_gate=count(patched,'REFERENCE_ONLY_DEADLINE_AFTER_EVAL_HANDLES')==1;
    I.after_metadata_gate=count(patched,'REFERENCE_ONLY_DEADLINE_AFTER_CERT_METADATA')==1;
    I.after_reuse_gate=count(patched,'REFERENCE_ONLY_DEADLINE_AFTER_REUSE_GATE')==1;
    I.continuous_sigma_guard=contains(patched,'specific_force_norm_LB_m_s2');
    I.c7_guard=contains(patched,'REFERENCE_ONLY_C7_CERTIFICATE_NOT_CLOSED');
    I.resource_gate=contains(patched,'af7r58i_prepare_batch_model(');
    I.trigger_assert=contains(patched,'obj.assert_trigger_packet_certificate_current();');
    I.reference_assert=contains(patched,'obj.assert_repaired_reference_current();');
    I.final_atomic_deadline=contains(patched,'finished after the hard online modification deadline');
    I.all=all(structfun(@(x)logical(x),I));
    assert(I.all,'[AF7R58ZZF] static safety invariant failed.');

    % New fail-fast gates must precede the first active-authority mutation.
    p1=strfind(patched,'REFERENCE_ONLY_DEADLINE_AFTER_RESOURCE_MODEL');
    p2=strfind(patched,'REFERENCE_ONLY_DEADLINE_AFTER_EVAL_HANDLES');
    p3=strfind(patched,'REFERENCE_ONLY_DEADLINE_AFTER_CERT_METADATA');
    p4=strfind(patched,'REFERENCE_ONLY_DEADLINE_AFTER_REUSE_GATE');
    pa=strfind(patched,'obj.active_repaired_reference=R;');
    assert(numel(p1)==1&&numel(p2)==1&&numel(p3)==1&&numel(p4)==1&&numel(pa)==1);
    assert(all([p1 p2 p3 p4] < pa), ...
        '[AF7R58ZZF] a fail-fast gate is not pre-authority.');

    say(fid,''); say(fid,'[B. STATIC SAFETY INVARIANTS]');
    fn=fieldnames(I);
    for k=1:numel(fn), say(fid,' %-34s = %d',fn{k},logical(I.(fn{k}))); end
    say(fid,' all fail-fast gates before active mutation = 1');

    % Full MATLAB class parse before production write.
    parseDir=fullfile(outdir,'AF7R58ZZF_PARSE');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZZF_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(patched,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    write_utf8(fullfile(parseDir,[parseName '.m']),parseText);
    addpath(parseDir,'-begin'); cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZZF] patched class parse failed.');
    eval(['clear ' parseName]);

    say(fid,''); say(fid,'[C. PREFLIGHT BEFORE WRITE]');
    say(fid,' exact source SHA = 1');
    say(fid,' exact payload SHA = 1');
    say(fid,' full class parse = 1');
    say(fid,' production writes = 0');

    [ok,msg]=mkdir(backupDir); assert(ok,'%s',msg);
    backupReady=true; OUT.backup_directory=backupDir;
    copyfile(pR,fullfile(backupDir,'REPLANNING_SYSTEM.m'));

    writesStarted=true;
    write_utf8(pR,patched); rehash;
    post=file_hash(pR);
    assert(strcmp(post,POST_SHA),'[AF7R58ZZF] post-write SHA mismatch.');

    OUT.post_sha=post; OUT.production_modified=true;
    OUT.status='FAILFAST_COMMIT_DEADLINE_GATES_INSTALLED__CLEAN_RERUN_REQUIRED';
    say(fid,''); say(fid,'[D. INSTALL RESULT]');
    say(fid,' production modified = 1');
    say(fid,' new accepting branches = 0');
    say(fid,' new reject-only deadline gates = 5');
    say(fid,' certificate/generator/controller math changed = 0');
    say(fid,' post SHA = %s',post);
catch ME
    if backupReady && writesStarted
        try
            copyfile(fullfile(backupDir,'REPLANNING_SYSTEM.m'),pR,'f');
            rehash; OUT.rollback_performed=true;
        catch
        end
    end
    OUT.production_modified=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_COMPLETE';
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    say(fid,''); say(fid,'[INSTALL FAILURE] %s | %s',ME.identifier,ME.message);
    say(fid,' rollback performed = %d',OUT.rollback_performed);
    say(fid,' production modified = 0');
end

save(fullfile(outdir,'AF7R58ZZF_OUT.mat'),'OUT','-v7');
assignin('base','AF7R58ZZF_OUT',OUT);
say(fid,''); say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',fullfile(outdir,'AF7R58ZZF_OUT.mat'));
say(fid,'status = %s',OUT.status);
end

function write_utf8(p,s)
fid=fopen(p,'wb');assert(fid>=0);c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=unicode2native(s,'UTF-8');n=fwrite(fid,b,'uint8');assert(n==numel(b));
end
function h=file_hash(p)
fid=fopen(p,'rb');assert(fid>=0);c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');m=java.security.MessageDigest.getInstance('SHA-256');m.update(b);
d=typecast(m.digest(),'uint8');h=lower(reshape(dec2hex(d,2).',1,[]));
end
function safe_rmpath(p)
try,q=strsplit(path,pathsep);if any(strcmpi(q,p)),rmpath(p);end,catch,end
end
function safe_fclose(fid)
try,if fid>=0,fclose(fid);end,catch,end
end
function say(fid,fmt,varargin)
s=sprintf(fmt,varargin{:});fprintf(1,'%s\n',s);fprintf(fid,'%s\n',s);
end
